CREATE TABLE T_ESTACAO (ID_ESTACAO BIGINT NOT NULL PRIMARY KEY, NM_ESTACAO VARCHAR(200) NOT NULL, ORDEM INTEGER NOT NULL, LINHA VARCHAR(30), ATIVA CHAR(1), SENTIDO VARCHAR(3), CONSTRAINT CK_ESTACAO_ATIVA CHECK (ATIVA IN ('S','N')));
CREATE TABLE T_FUNCIONARIO (ID_FUNCIONARIO BIGINT NOT NULL PRIMARY KEY, NM_FUNCIONARIO VARCHAR(200) NOT NULL, CPF CHAR(11) NOT NULL, EMAIL VARCHAR(200), SENHA VARCHAR(200), CARGO VARCHAR(60) NOT NULL);
CREATE TABLE T_USUARIO (ID_USUARIO BIGINT NOT NULL PRIMARY KEY, NM_USUARIO VARCHAR(200) NOT NULL, EMAIL VARCHAR(200) NOT NULL, SENHA VARCHAR(200) NOT NULL);
CREATE TABLE T_OCORRENCIA (ID_OCORRENCIAN BIGINT NOT NULL PRIMARY KEY, TIPO_PROBLEMA VARCHAR(100) NOT NULL, MENSAGEM CLOB NOT NULL, STATUS CHAR(1) NOT NULL, DT_INICIO TIMESTAMP NOT NULL, DT_FIM TIMESTAMP, FK_ID_FUNCIONARIO BIGINT NOT NULL, FK_ID_ESTACAO BIGINT NOT NULL, CONSTRAINT FK_OCORR_FUNC FOREIGN KEY (FK_ID_FUNCIONARIO) REFERENCES T_FUNCIONARIO(ID_FUNCIONARIO), CONSTRAINT FK_OCORR_EST FOREIGN KEY (FK_ID_ESTACAO) REFERENCES T_ESTACAO(ID_ESTACAO));
CREATE UNIQUE INDEX UK_USUARIO_EMAIL ON T_USUARIO(EMAIL);
CREATE UNIQUE INDEX UK_FUNCIONARIO_EMAIL ON T_FUNCIONARIO(EMAIL);
CREATE SEQUENCE SEQ_ESTACAO START WITH 100 INCREMENT BY 1;
CREATE SEQUENCE SEQ_FUNCIONARIO START WITH 100 INCREMENT BY 1;
CREATE SEQUENCE SEQ_USUARIO START WITH 100 INCREMENT BY 1;
CREATE SEQUENCE SEQ_OCORRENCIA START WITH 100 INCREMENT BY 1;
